1	# Clinical truth model
2	
3	The generator's source-neutral record of what actually happened to each patient. Renderers turn it into
4	each source's items ([HERO.md](HERO.md#sources)); answer keys are computed from it directly. Nothing in
5	the truth knows about any source's codes, units or statuses beyond a canonical choice made here.
6	
7	Design rules:
8	
9	- **Canonical units and codes.** Labs in one unit per analyte (mg/dL, 10³/µL, mmol/L for electrolytes
10	  and ketones, mL/min/1.73m²); conditions carry SNOMED + ICD-10; meds carry RxNorm ingredient + strength.
11	  Renderers convert *away* from canonical; answer keys stay canonical.
12	- **Events, not states.** Med and condition histories are lists of dated status changes; "current"
13	  is derived.
14	- **Every fact says who could know it.** `visibility` lists the sources that record the fact and in what
15	  modality (prose, structured, both). That drives renderers and lets us score prose-only facts
16	  separately.
17	- **Traps are data.** A planted trap is a tagged property of a fact (`traps: ["T3"]`), so trap coverage is
18	  a query over the truth.
19	
20	## Type sketch
21	
22	```ts
23	type SourceKey = "A" | "B" | "C" | "P";
24	type Modality = "prose" | "structured" | "both";
25	type Visibility = Partial<Record<SourceKey, Modality>>;
26	type TrapId = `T${number}`;
27	
28	interface FuzzyDate { value: string; precision: "year" | "month" | "day" | "instant"; tz?: string } // value ISO, local
29	interface Coding { system: "snomed" | "icd10" | "rxnorm" | "loinc"; code: string; display: string }
30	
31	interface Patient {
32	  id: string;                    // truth id, never rendered
33	  demographics: { name: string; birthDate: string; sex: "F" | "M"; race?: string; tz: string };
34	  sources: Record<SourceKey, { localId: string } | undefined>;   // which sources know the patient
35	  sensitivity: { category: "behavioral-health" | "reproductive" | "substance-use"; factIds: string[] }[];
36	  encounters: Encounter[]; conditions: Condition[]; meds: Medication[]; labs: LabResult[];
37	  vitals: Vital[]; allergies: AllergyIntolerance[]; narrativeFacts: NarrativeFact[];
38	}
39	
40	interface Encounter {
41	  id: string; source: SourceKey; kind: "office" | "ed" | "inpatient" | "telehealth" | "lab-only" | "home";
42	  start: FuzzyDate; end?: FuzzyDate; reason: string; clinician?: string;
43	  documents: { kind: "ed-note" | "h&p" | "progress" | "consult" | "discharge" | "office-note" | "letter"
44	                    | "patient-note";
45	               at: FuzzyDate; factIds: string[] }[];   // which facts each document mentions (drives prose + re-snapshots, T15)
46	}
47	
48	interface Condition {
49	  id: string; coding: Coding[]; onset: FuzzyDate;      // T10/T17
50	  history: { at: FuzzyDate; status: "active" | "resolved" | "ruled-out"; stage?: string; recordedBy: SourceKey }[];
51	  visibility: Visibility; traps?: TrapId[];
52	}
53	
54	interface Medication {
55	  id: string; rxnorm: Coding; doseText: string; dose?: { value: number; unit: string }; frequency: string;
56	  otc?: boolean;                                        // bought without a prescription (ibuprofen); usually only P knows
57	  history: { at: FuzzyDate; status: "active" | "held" | "stopped" | "entered-in-error";
58	             reason?: string; by: SourceKey; intendResume?: boolean;   // T1, T4
59	             doseText?: string; dose?: { value: number; unit: string }; frequency?: string;
60	                                                        // set on a dose change (losartan 50 → 100 mg 2025-08,
61	                                                        // metformin 1000 → 500 mg BID 2026-02); the top-level
62	                                                        // dose is the starting one
63	             takenAs?: string }[];                      // how the patient actually takes it when that differs
64	                                                        // from the prescription (self-adjusted glargine), by: "P"
65	  laggingLines?: { source: SourceKey; showsStatus: "active" | "held" | "stopped"; since: FuzzyDate }[];
66	                                                        // a source's copy that was never updated (B's outside finerenone line, T1)
67	  visibility: Visibility; traps?: TrapId[];
68	}
69	
70	interface LabResult {
