1	// Clinical truth model: the source-neutral record of what happened to each patient.
2	// Follows truth/MODEL.md. Deviations from the sketch there are listed in packages/truth/README.md.
3	//
4	// Times: an "instant" is an RFC 3339 string with the offset in effect in the patient's zone
5	// ("2024-11-01T21:40:00-05:00"). A "date" is a full or partial local date ("2016", "2016-06",
6	// "2016-06-14"); its precision is the string's precision. `When` is either.
7	
8	export type SourceKey = "A" | "B" | "C" | "P";
9	export type Modality = "prose" | "structured" | "both";
10	export type Visibility = Partial<Record<SourceKey, Modality>>;
11	export type TrapId = `T${number}`;
12	export type When = string;
13	
