20	    given: string; family: string; birthDate: string; sex: "F" | "M";
21	    race?: string; tz: string; occupation?: string;
22	  };
23	  /** Which sources know the patient, with the patient's id at that source. */
24	  sources: Partial<Record<SourceKey, { localId: string }>>;
25	  sensitivity: { category: "behavioral-health" | "reproductive" | "substance-use"; factIds: string[] }[];
26	  encounters: Encounter[];
27	  conditions: Condition[];
28	  meds: Medication[];
29	  draws: LabDraw[];
30	  labs: LabResult[];
31	  vitals: Vital[];
32	  allergies: AllergyIntolerance[];
33	  narrativeFacts: NarrativeFact[];
34	  /** Things only the patient's app holds that are not clinical facts (diary days, list saves, meter settings). */
35	  home?: HomeLogPlan;
36	  /** Outbound referrals (Northgate refers to Lakeview nephrology). */
37	  referrals?: Referral[];
38	  /** Planted traps: which facts carry which trap. Derived for the hero, chosen by the generator otherwise. */
39	  traps: TrapAssignment[];
40	}
41	
42	export interface Referral {
43	  id: string;
44	  by: SourceKey;
45	  author: string;                              // Staff id
46	  encounter?: string;                          // encounter it was written at
