101	/** One structured element of a hospital document. Home meds and allergies are always re-listed (T15). */
102	export type DocItem =
103	  | { kind: "vitals"; vitalId: string }
104	  | { kind: "lab"; labIds: string[]; panel?: string; key?: string }
105	  | { kind: "dx"; conditionId: string; rank?: "principal" | "secondary" }
