109	  | { kind: "follow-up"; key?: string; with: string; when: string; purpose: string }
110	  | { kind: "allergies" }                      // position of the re-listed allergy list (default: end)
111	  | { kind: "home-meds" };                     // position of the re-listed home med list (default: end)
112	
113	export type ConditionStatus = "active" | "resolved" | "ruled-out" | "working";
114	
115	export interface Condition {
116	  id: string;
117	  name: string;                                // canonical display
118	  coding: Coding[];                            // SNOMED + ICD-10
119	  onset: When;                                 // partial dates allowed (T10/T17)
120	  history: {
121	    at: When; status: ConditionStatus; stage?: string; recordedBy: SourceKey;
122	    /** How the recording source worded it, when that matters (hospital working diagnoses). */
