353	export function inZone(instant: string, tz = "America/Chicago"): string {
354	  const t = ms(instant);
355	  const off = tzOffsetMinutes(t, tz);
356	  const d = new Date(t + off * 60000).toISOString().slice(0, 19);
357	  const o = fmtOffset(off);
358	  return d + (o === "Z" ? "+00:00" : o);
359	}
360	
361	export function utcZ(instant: string): string {
362	  return new Date(ms(instant)).toISOString().replace(/\.\d{3}Z$/, "Z");
363	}
364	
365	/** Local wall-clock "YYYY-MM-DDTHH:MM" of an instant. */
366	export function wall(instant: string, tz = "America/Chicago"): string {
367	  return inZone(instant, tz).slice(0, 16);
368	}
369	
370	export function localDate(w: When, tz = "America/Chicago"): string {
371	  return w.includes("T") ? inZone(w, tz).slice(0, 10) : w;
372	}
373	
374	export function addMinutes(instant: string, min: number, tz = "America/Chicago"): string {
375	  return inZone(new Date(ms(instant) + min * 60000).toISOString(), tz);
376	}
377	
378	export function addDays(date: string, days: number): string {
379	  const d = new Date(Date.parse(date.slice(0, 10) + "T12:00:00Z") + days * 86400000);
380	  return d.toISOString().slice(0, 10);
381	}
