383	export function daysBetween(a: string, b: string): number {
384	  return Math.round((Date.parse(b.slice(0, 10) + "T12:00:00Z") - Date.parse(a.slice(0, 10) + "T12:00:00Z")) / 86400000);
385	}
386	
387	/** Sort key for a When: partial dates sort at their start. */
388	export function sortKey(w: When): number {
389	  if (w.includes("T")) return ms(w);
390	  const full = w.length === 4 ? `${w}-01-01` : w.length === 7 ? `${w}-01` : w;
391	  return Date.parse(full + "T00:00:00-06:00");
392	}
393	
394	export function ageOn(birthDate: string, date: string): number {
395	  const [by, bm, bd] = birthDate.split("-").map(Number);
396	  const [y, m, d] = date.slice(0, 10).split("-").map(Number);
397	  return y - by - (m < bm || (m === bm && d < bd) ? 1 : 0);
398	}
399	
400	// ─── eGFR ───────────────────────────────────────────────────────────────────────────────────────
401	
402	/** CKD-EPI 2021 (race-free). */
403	export function ckdEpi2021(scr: number, age: number, sex: "F" | "M"): number {
404	  const k = sex === "F" ? 0.7 : 0.9;
405	  const a = sex === "F" ? -0.241 : -0.302;
406	  const r = scr / k;
407	  return 142 * Math.min(r, 1) ** a * Math.max(r, 1) ** -1.2 * 0.9938 ** age * (sex === "F" ? 1.012 : 1);
408	}
409	
410	/** CKD-EPI 2009, with or without the race coefficient. */
411	export function ckdEpi2009(scr: number, age: number, sex: "F" | "M", black: boolean): number {
412	  const k = sex === "F" ? 0.7 : 0.9;
413	  const a = sex === "F" ? -0.329 : -0.411;
414	  const r = scr / k;
415	  return 141 * Math.min(r, 1) ** a * Math.max(r, 1) ** -1.209 * 0.993 ** age * (sex === "F" ? 1.018 : 1) * (black ? 1.159 : 1);
416	}
417	
418	export const EGFR_2021_FROM = "2022-01-10";        // Lakeview switched equations
