1	// Per-source expected views: what a correct reader of ONE source's records alone should conclude, as of
2	// a date. Computed from the clinical truth (packages/truth) plus knowledge of how each renderer
3	// (packages/render) writes the truth into that source, never from the rendered items themselves. So a
4	// stale Northgate outside line shows finerenone active in Northgate's key even though the truth says
5	// held, and Riverside's key lists cough as an intolerance because Riverside's reaction text says cough.
6	//
7	// Each expected row carries: the fields that are scored, the truth ids it rests on (`basis`), the traps
8	// those facts carry in this source, and whether the source narrates the fact. "Anti rows" are facts the
9	// source renders that must NOT appear in a correct mapper's output (a withdrawn potassium, a voided
10	// order, a ruled-out diagnosis); a mapper row that matches one is a trap error.
11	
12	import { drug, MGDL_PER_MMOL_GLUCOSE } from "../../truth/src/catalog.ts";
13	import {
14	  at as localAt, EGFR_2021_FROM, inZone, localDate, type LabResult, type Medication, ms, type Patient, type SourceKey, sortKey, wall,
15	} from "../../truth/src/model.ts";
16	import { medDoseAt } from "../../render/src/describe.ts";
17	import { icdDisplay } from "../../render/src/context.ts";
18	
19	export type Modality = "structured" | "narrated" | "prose-only";
20	
21	export interface KeyRow<F> {
22	  view: "medications" | "problems" | "allergies" | "labs" | "vitals";
23	  /** Fields compared with the mapper's row (undefined = not scored). */
24	  fields: F;
25	  basis: string[];
26	  traps: string[];
27	  modality: Modality;
28	  /** Not scored: recency used to keep one row per ingredient (the view's rule) when a source has several. */
29	  order?: number;
30	}
31	
32	export interface MedKey {
33	  ingredient: string;               // truth ingredient (match key)
34	  names: string[];                  // other names a mapper may use (as written by the source)
35	  ingredientDerivable: boolean;     // false when the source does not say which drug (patient typed "water pill")
36	  status: "active" | "held" | "stopped" | "unknown";
37	  status_since?: string;            // scored only where the source dates the status change
38	  dose?: { value: number; unit: string };
39	  frequency?: string[];             // acceptable codes
40	  stop_reason?: string;
41	  /** false: do not score `ingredient` (US Core output need not carry it when an RxNorm product code is given). */
42	  scoreIngredient?: boolean;
43	}
44	export interface ProblemKey { family: string; condition: string; icd10?: string; status: "active" | "resolved"; ckd_stage?: string; onset?: { value: string; precision: string } }
45	export interface AllergyKey { substance: string; type: "allergy" | "intolerance" | "adverse_reaction"; criticality?: "low" | "high" | "unknown"; onset?: { value: string; precision: string } }
46	export interface LabKey { analyte: string; value: number; comparator?: string; unit: string; collected: string; egfr_equation?: string }
47	export interface VitalKey {
48	  setting: "clinic" | "hospital" | "home"; local_time: string;
49	  systolic_mmhg?: number; diastolic_mmhg?: number; repeat_systolic_mmhg?: number; repeat_diastolic_mmhg?: number;
50	  pulse_bpm?: number; weight_kg?: number; glucose_mg_dl?: number;
51	}
52	
53	export interface Expected {
54	  medications: KeyRow<MedKey>[];
55	  problems: KeyRow<ProblemKey>[];
56	  allergies: KeyRow<AllergyKey>[];
57	  labs: KeyRow<LabKey>[];
58	  vitals: KeyRow<VitalKey>[];
59	  anti: KeyRow<Partial<MedKey & ProblemKey & LabKey & VitalKey> & { reason: string }>[];
60	}
61	
62	export const SOURCE_KEY: Record<string, SourceKey> = { riverside: "A", northgate: "B", lakeview: "C", homelog: "P" };
63	
64	/** End of the local day `asOf` (America/Chicago) as epoch ms. */
65	export function endOfDay(asOf: string): number {
66	  return ms(localAt(`${asOf}T23:59:59`));
67	}
68	
69	const ld = (w: string) => localDate(w);
70	const stageOf = (s?: string) => {
71	  if (!s) return {};
72	  const m = s.match(/^(\d[ab]?)(?:\s+(A\d))?/);
73	  return m ? { ckd_stage: `G${m[1]}`, albuminuria: m[2] } : {};
74	};
75	const onsetOf = (w: string) => ({ value: w.includes("T") ? localDate(w) : w, precision: w.includes("T") || w.length === 10 ? "day" : w.length === 7 ? "month" : "year" });
76	const doseOf = (d?: { value: number; unit: string }) => (d ? { value: d.value, unit: d.unit === "units" || d.unit === "unit" ? "units" : d.unit } : undefined);
77	const FREQ_OK: Record<string, string[]> = { QD: ["QD"], BID: ["BID"], TID: ["TID"], QHS: ["QHS"], QW: ["QW", "other"], PRN: ["PRN"] };
78	
79	export const ANALYTE_KEY: Record<string, string> = { "anion-gap": "anion_gap" };
80	const analyteName = (a: string) => ANALYTE_KEY[a] ?? a;
81	const UNIT: Record<string, string> = {
82	  creatinine: "mg/dL", egfr: "mL/min/1.73m2", potassium: "mmol/L", sodium: "mmol/L", chloride: "mmol/L", bicarbonate: "mmol/L", anion_gap: "mmol/L",
83	  bun: "mg/dL", glucose: "mg/dL", a1c: "%", uacr: "mg/g", platelets: "10*3/uL", wbc: "10*3/uL", hemoglobin: "g/dL", bhb: "mmol/L", ph: "[pH]",
84	  pco2: "mmHg", lipase: "U/L", troponin: "ng/mL", cholesterol: "mg/dL", triglycerides: "mg/dL", hdl: "mg/dL", ldl: "mg/dL",
85	};
86	// Decimal places each source prints (renderers' tables).
87	const DEC_C: Record<string, number> = { creatinine: 2, sodium: 0, potassium: 1, glucose: 0, a1c: 1, uacr: 0, wbc: 1, hemoglobin: 1, platelets: 0, cholesterol: 0, triglycerides: 0, hdl: 0, ldl: 0, egfr: 0 };
88	const DEC_A: Record<string, number> = {
89	  sodium: 0, potassium: 1, chloride: 0, bicarbonate: 0, "anion-gap": 0, bun: 0, creatinine: 2, egfr: 0, glucose: 0, ph: 2, pco2: 0, bhb: 1, troponin: 2,
90	  lipase: 0, wbc: 1, hemoglobin: 1, platelets: 0, a1c: 1, uacr: 0, cholesterol: 0, triglycerides: 0, hdl: 0, ldl: 0,
91	};
92	const round = (v: number, d: number) => Number(v.toFixed(d));
93	
94	// ─── Trap tags and modality ────────────────────────────────────────────────────────────────────────
95	
96	export interface TrapIndex { /** truth id -> traps carried by the fact in the truth (fact-level and assignments). */ fact: Map<string, Set<string>>; /** `${source}|${truthId}` -> traps on rendered items of that source mentioning the fact. */ item: Map<string, Set<string>> }
97	
98	export function factTraps(p: Patient): Map<string, Set<string>> {
99	  const ft = new Map<string, Set<string>>();
100	  const add = (f: string, t: string) => { if (!ft.has(f)) ft.set(f, new Set()); ft.get(f)!.add(t); };
101	  for (const a of p.traps) for (const f of a.factIds) add(f, a.trap);
102	  for (const x of [...p.meds, ...p.labs, ...p.conditions, ...p.allergies, ...p.narrativeFacts] as { id: string; traps?: string[] }[]) for (const t of x.traps ?? []) add(x.id, t);
103	  return ft;
104	}
105	
106	/** Traps of a fact in a source: fact-level traps that the source's rendered items also carry. */
107	export function trapsFor(ix: TrapIndex, s: SourceKey, ids: string[]): string[] {
108	  const out = new Set<string>();
109	  for (const id of ids) {
110	    const f = ix.fact.get(id), it = ix.item.get(`${s}|${id}`);
111	    if (f && it) for (const t of f) if (it.has(t)) out.add(t);
112	  }
113	  return [...out].sort((a, b) => +a.slice(1) - +b.slice(1));
114	}
115	
116	function modality(v: { visibility?: Partial<Record<SourceKey, string>> } | undefined, s: SourceKey): Modality {
117	  const m = v?.visibility?.[s];
118	  return m === "both" ? "narrated" : m === "prose" ? "prose-only" : "structured";
119	}
120	
121	// ─── Per-source keys ───────────────────────────────────────────────────────────────────────────────
122	
123	export function expectedFor(p: Patient, source: string, asOf: string, ix: TrapIndex): Expected {
124	  const s = SOURCE_KEY[source];
125	  const t = endOfDay(asOf);
126	  const e: Expected = { medications: [], problems: [], allergies: [], labs: [], vitals: [], anti: [] };
127	  if (!p.sources[s]) return e;
128	  if (s === "B") northgate(p, t, e, ix);
129	  if (s === "C") lakeview(p, t, e, ix);
130	  if (s === "A") riverside(p, t, e, ix);
131	  if (s === "P") homelog(p, t, e, ix);
132	  // The view keeps one row per ingredient: the most recent line/order/entry.
133	  const best = new Map<string, KeyRow<MedKey>>();
134	  for (const r of e.medications) {
135	    const k = r.fields.ingredientDerivable ? r.fields.ingredient : `name:${r.fields.names[0]}`;
136	    const prev = best.get(k);
137	    if (!prev || (r.order ?? 0) > (prev.order ?? 0)) best.set(k, r);
138	  }
139	  e.medications = [...best.values()];
140	  return e;
141	}
142	
143	function row<F>(view: KeyRow<F>["view"], fields: F, basis: string[], s: SourceKey, ix: TrapIndex, mod: Modality, extraTraps: string[] = []): KeyRow<F> {
144	  const traps = [...new Set([...trapsFor(ix, s, basis), ...extraTraps])].sort((a, b) => +a.slice(1) - +b.slice(1));
145	  return { view, fields, basis, traps, modality: mod };
146	}
147	
148	// Northgate: event log; lists replayed per line id; outside lines lag (T1); imported copies of Lakeview results.
149	function northgate(p: Patient, t: number, e: Expected, ix: TrapIndex) {
150	  const encs = p.encounters.filter((x) => x.source === "B").sort((a, b) => ms(a.start) - ms(b.start));
151	  const firstEnc = encs[0];
152	
153	  // Medication lines.
154	  interface Line { med: Medication; events: { at: string; action: string; status: string }[]; outside?: boolean; voided?: boolean; voidAt?: string }
155	  const lines: Line[] = [];
156	  for (const m of p.meds.filter((x) => x.setting !== "inpatient")) {
157	    let cur: Line | undefined;
158	    let state: string | undefined;
159	    for (const h of m.history.filter((x) => x.by === "B")) {
160	      let at = h.at;
161	      if (!at.includes("T")) { if (!firstEnc) continue; at = new Date(ms(firstEnc.start) + (15 + p.meds.indexOf(m)) * 60000).toISOString(); }
162	      if (h.status === "entered-in-error") { if (cur) { cur.voided = true; cur.voidAt = at; } cur = undefined; state = undefined; continue; }
163	      let action: string | undefined;
164	      if (!cur) { if (h.status !== "active") continue; cur = { med: m, events: [] }; lines.push(cur); action = "start"; state = "active"; }
165	      else if (h.status === "stopped") action = "stop";
166	      else if (h.status === "held") { action = state === "held" ? undefined : "hold"; state = "held"; }
167	      else if (h.status === "active" && state === "held") { action = "resume"; state = "active"; }
168	      else if (h.status === "active" && (h.dose || h.product || h.frequency)) action = "change";
169	      if (!action) continue;
170	      cur.events.push({ at, action, status: action === "stop" ? "stopped" : action === "hold" ? "held" : "active" });
171	      if (action === "stop") { cur = undefined; state = undefined; }
172	    }
173	    for (const lag of m.laggingLines ?? []) if (lag.source === "B") lines.push({ med: m, outside: true, events: [{ at: lag.since, action: "start", status: "active" }] });
174	  }
175	  const byIngredient = new Map<string, Line[]>();
176	  for (const l of lines) {
177	    const ev = l.events.filter((x) => ms(x.at) <= t);
178	    if (!ev.length) continue;
179	    if (l.voided && l.voidAt && ms(l.voidAt) <= t) {
180	      e.anti.push(row("medications", { reason: "voided (entered in error) medication line", ingredient: drug(l.med.product).ingredient, dose: doseOf(medDoseAt(p, l.med.id, ev[0].at).dose) }, [l.med.id], "B", ix, "structured", ["T4"]));
181	      continue;
182	    }
183	    const ing = drug(medDoseAt(p, l.med.id, ev[ev.length - 1].at).product).ingredient;
184	    byIngredient.set(ing, [...(byIngredient.get(ing) ?? []), l]);
185	  }
186	  for (const [ing, ls] of byIngredient) {
187	    const last = (l: Line) => ms(l.events.filter((x) => ms(x.at) <= t).slice(-1)[0].at);
188	    const l = [...ls].sort((a, b) => last(b) - last(a))[0];
189	    const ev = l.events.filter((x) => ms(x.at) <= t);
190	    const cur = ev[ev.length - 1];
191	    let sinceIdx = ev.length - 1;
192	    while (sinceIdx > 0 && ev[sinceIdx - 1].status === cur.status && cur.status !== "active") sinceIdx--;
193	    if (cur.status === "active") sinceIdx = ev.map((x) => x.action).lastIndexOf(ev.some((x) => x.action === "resume") ? "resume" : "start");
194	    const d = l.outside ? { dose: l.med.dose, frequency: l.med.frequency, product: l.med.product } : medDoseAt(p, l.med.id, cur.action === "stop" || cur.action === "hold" ? new Date(ms(cur.at) - 60000).toISOString() : cur.at);
195	    const h = [...l.med.history].reverse().find((x) => x.by === "B" && x.status === "stopped" && Math.abs(sortKey(x.at) - ms(cur.at)) < 120000);
196	    e.medications.push(row("medications", {
197	      ingredient: ing, names: [drug(d.product).scdName], ingredientDerivable: true, status: cur.status as MedKey["status"],
198	      status_since: cur.status === "active" ? undefined : ld(ev[sinceIdx].at),
199	      dose: doseOf(d.dose), frequency: FREQ_OK[d.frequency], stop_reason: cur.status === "stopped" ? h?.stopReason ?? "other" : undefined,
200	    }, [l.med.id], "B", ix, modality(l.med, "B"), l.outside ? ["T1"] : []));
201	    e.medications[e.medications.length - 1].order = ms(cur.at);
202	  }
203	
204	  // Problems.
205	  for (const c of p.conditions) {
206	    const bh = c.history.filter((h) => h.recordedBy === "B" && sortKey(h.at) <= t);
207	    if (!bh.length) continue;
208	    const last = bh[bh.length - 1];
209	    const stage = [...bh].reverse().find((h) => h.stage)?.stage;
210	    const icd = [...bh].reverse().find((h) => h.icd10)?.icd10 ?? c.coding.find((x) => x.system === "icd10")!.code;
211	    e.problems.push(row("problems", {
212	      family: family(icd, c.name), condition: c.name, icd10: icd, status: last.status === "resolved" ? "resolved" : "active",
213	      ...(/^N18/.test(icd) ? { ckd_stage: stageOf(stage).ckd_stage } : {}), onset: onsetOf(c.onset),
214	    } as ProblemKey, [c.id], "B", ix, modality(c, "B")));
215	  }
216	
217	  // Allergies.
218	  for (const a of p.allergies.filter((x) => x.recordedBy === "B" && sortKey(x.recordedAt) <= t)) {
219	    e.allergies.push(row("allergies", { substance: a.substance.display, type: a.type === "adverse-reaction" ? "adverse_reaction" : a.type, criticality: a.criticality, onset: onsetOf(a.onset) } as AllergyKey, [a.id], "B", ix, modality(a, "B")));
220	  }
221	
222	  // Imported results (copies of Lakeview results with copies including B).
223	  const drawsWithB = new Set(p.labs.filter((l) => l.copies?.includes("B")).map((l) => l.draw));
224	  for (const l of p.labs) {
225	    if (l.performedBy !== "C" || !drawsWithB.has(l.draw) || l.duplicateOf || !l.copies?.includes("B")) continue;
226	    if (!l.resultedAt || ms(l.resultedAt) > t) continue;
227	    labRows(p, l, "B", t, e, ix);
228	  }
229	
230	  // Vitals.
231	  for (const v of p.vitals.filter((x) => x.source === "B" && ms(x.at) <= t)) {
232	    if (!encs.some((x) => localDate(x.start) === localDate(v.at))) continue;
233	    e.vitals.push(row("vitals", {
234	      setting: "clinic", local_time: wall(v.at), ...(v.bp ? { systolic_mmhg: v.bp.systolic, diastolic_mmhg: v.bp.diastolic } : {}),
235	      ...(v.bpRepeat ? { repeat_systolic_mmhg: v.bpRepeat.systolic, repeat_diastolic_mmhg: v.bpRepeat.diastolic } : {}),
236	      ...(v.pulse !== undefined ? { pulse_bpm: v.pulse } : {}), ...(v.weightKg !== undefined ? { weight_kg: Math.round(Math.round((v.weightKg / 0.45359237) * 10) / 10 * 0.45359237 * 10) / 10 } : {}),
237	    } as VitalKey, [v.id], "B", ix, "structured"));
238	  }
239	}
