241	/** A Lakeview result as Lakeview (C) or its Northgate copy (B) reports it; withdrawn values become anti rows. */
242	function labRows(p: Patient, l: LabResult, s: "B" | "C", t: number, e: Expected, ix: TrapIndex) {
243	  const a = analyteName(l.analyte);
244	  const withdrawn = l.status === "corrected-away" && (!l.correctedAt || ms(l.correctedAt) <= t);
245	  if (l.status === "entered-in-error") return;
246	  const mod = modality(l, s);
247	  if (l.analyte === "egfr") {
248	    const rep = (l.reported ?? []).find((r) => r.equation === "ckd-epi-2009-nonaa") ?? (l.reported ?? []).find((r) => r.equation === "ckd-epi-2021") ?? { equation: "ckd-epi-2021" as const, value: l.value };
249	    const fields: LabKey = { analyte: "egfr", value: rep.value, ...(rep.comparator ? { comparator: rep.comparator } : {}), unit: UNIT.egfr, collected: l.collectedAt, egfr_equation: rep.equation === "ckd-epi-2021" ? "ckd-epi-2021" : "ckd-epi-2009" };
250	    const aa = (l.reported ?? []).find((r) => r.equation === "ckd-epi-2009-aa");
251	    // eGFR rows depend on the creatinine they were calculated from.
252	    const cr = p.labs.find((x) => x.id === l.derivedFrom?.[0]);
253	    const crWithdrawn = cr && cr.status === "corrected-away" && (!cr.correctedAt || ms(cr.correctedAt) <= t);
254	    if (crWithdrawn) { e.anti.push(row("labs", { ...fields, reason: "eGFR from a withdrawn creatinine" }, [l.id], s, ix, mod, ["T3"])); return; }
255	    if (aa && aa.value !== rep.value) e.anti.push(row("labs", { analyte: "egfr", value: aa.value, ...(aa.comparator ? { comparator: aa.comparator } : {}), collected: l.collectedAt, reason: "race-coefficient eGFR variant" }, [l.id], s, ix, mod, ["T11"]));
256	    e.labs.push(row("labs", fields, [l.id], s, ix, mod, ms(l.collectedAt) < Date.parse(EGFR_2021_FROM) ? ["T11"] : []));
257	    return;
258	  }
259	  const v = round(l.value, DEC_C[l.analyte] ?? 1);
260	  const fields: LabKey = { analyte: a, value: v, ...(l.comparator ? { comparator: l.comparator } : {}), unit: UNIT[a], collected: l.collectedAt };
261	  if (withdrawn) { e.anti.push(row("labs", { ...fields, reason: "result withdrawn by the lab (corrected away)" }, [l.id], s, ix, mod, ["T3"])); return; }
262	  e.labs.push(row("labs", fields, [l.id], s, ix, mod));
263	}
