265	// Lakeview: table rows; requisitions superseded on correction; med status in MED_STATUS_HIST rows.
266	function lakeview(p: Patient, t: number, e: Expected, ix: TrapIndex) {
267	  const contacts = p.encounters.filter((x) => x.source === "C" && ms(x.start) <= t).sort((a, b) => ms(a.start) - ms(b.start));
268	  const contactDays = new Set(contacts.map((c) => localDate(c.start)));
269	
270	  for (const m of p.meds) {
271	    const ce = m.history.filter((h) => h.by === "C" && contactDays.has(localDate(h.at)) && sortKey(h.at) <= t);
272	    if (!ce.length) continue;
273	    const last = ce[ce.length - 1];
274	    const d = drug(ce[0].product ?? m.product);
275	    if (last.status === "entered-in-error" || ce[0].status === "entered-in-error") {
276	      e.anti.push(row("medications", { reason: "prescription entered in error", ingredient: d.ingredient }, [m.id], "C", ix, "structured", ["T4"]));
277	      continue;
278	    }
279	    let i = ce.length - 1;
280	    while (i > 0 && ce[i - 1].status === last.status) i--;
281	    const status = last.status === "stopped" ? "stopped" : last.status === "held" ? "held" : "active";
282	    e.medications.push(row("medications", {
283	      ingredient: d.ingredient, names: [`${d.ingredient} ${d.strength} mg ${d.form}`], ingredientDerivable: true, status,
284	      status_since: status === "active" ? undefined : ld(ce[i].at), dose: doseOf(ce[0].dose ?? m.dose), frequency: FREQ_OK[m.frequency],
285	    }, [m.id], "C", ix, modality(m, "C"), ce.some((h) => h.status === "held") ? ["T1"] : []));
286	    e.medications[e.medications.length - 1].order = sortKey(last.at);
287	  }
288	
289	  // Problems: latest VISIT_DX per condition; 'R' and 'P' are not problems.
290	  const latest = new Map<string, { status?: string; icd?: string; label?: string; at: string }>();
291	  for (const c of contacts) for (const a of c.addressed ?? []) latest.set(a.conditionId, { status: a.status, icd: a.icd10, label: a.label, at: c.start });
292	  let stage: { g: string; a?: string } | undefined;
293	  for (const c of contacts) if (c.ckdCategory) stage = c.ckdCategory;
294	  for (const [cid, st] of latest) {
295	    const c = p.conditions.find((x) => x.id === cid)!;
296	    const icd = st.icd ?? [...c.history].reverse().find((h) => h.icd10 && sortKey(h.at) <= ms(st.at))?.icd10 ?? c.coding.find((x) => x.system === "icd10")!.code;
297	    const text = st.label ?? icdDisplay(icd);
298	    if (st.status === "ruled-out" || st.status === "working") {
299	      e.anti.push(row("problems", { reason: `diagnosis ${st.status} at the latest contact`, family: family(icd, text), condition: text }, [c.id], "C", ix, "structured", ["T12"]));
300	      continue;
301	    }
302	    e.problems.push(row("problems", {
303	      family: family(icd, text), condition: text, icd10: icd, status: st.status === "history" ? "resolved" : "active",
304	      ...(/^N18/.test(icd) && stage ? { ckd_stage: stage.g } : {}),
305	    } as ProblemKey, [c.id], "C", ix, modality(c, "C"), /^N18/.test(icd) && stage ? ["T5"] : []));
306	  }
307	
308	  for (const l of p.labs) {
309	    if (l.performedBy !== "C" || !l.resultedAt || ms(l.resultedAt) > t) continue;
310	    if (l.duplicateOf || l.status === "entered-in-error") {
311	      e.anti.push(row("labs", { reason: "result of an order entered in error (duplicate order)", analyte: analyteName(l.analyte), value: round(l.value, DEC_C[l.analyte] ?? 1), collected: l.collectedAt }, [l.id], "C", ix, "structured", ["T4"]));
312	      continue;
313	    }
314	    labRows(p, l, "C", t, e, ix);
315	  }
316	
317	  for (const v of p.vitals.filter((x) => x.source === "C" && ms(x.at) <= t && contactDays.has(localDate(x.at)))) {
318	    e.vitals.push(row("vitals", {
319	      setting: "clinic", local_time: wall(v.at), ...(v.bp ? { systolic_mmhg: v.bp.systolic, diastolic_mmhg: v.bp.diastolic } : {}),
320	      ...(v.bpRepeat ? { repeat_systolic_mmhg: v.bpRepeat.systolic, repeat_diastolic_mmhg: v.bpRepeat.diastolic } : {}),
321	      ...(v.pulse !== undefined ? { pulse_bpm: v.pulse } : {}), ...(v.weightKg !== undefined ? { weight_kg: v.weightKg } : {}),
322	    } as VitalKey, [v.id], "C", ix, "structured"));
323	  }
324	}
