326	// Riverside: documents; each re-lists home meds and allergies (T15); labs are copies (T14); UTC times (T10).
327	function riverside(p: Patient, t: number, e: Expected, ix: TrapIndex) {
328	  const docs = p.encounters.filter((x) => x.source === "A").flatMap((enc) => enc.documents.map((doc) => ({ enc, doc })))
329	    .filter((x) => ms(x.doc.signedAt) <= t).sort((a, b) => ms(a.doc.signedAt) - ms(b.doc.signedAt));
330	  if (!docs.length) return;
331	  const { enc, doc } = docs[docs.length - 1];
332	  const isDischarge = doc.kind === "discharge";
333	
334	  // Home medication list of the latest document.
335	  const CLASS_SKIP = (m: Medication) => m.setting === "inpatient" || !m.visibility.A || m.otc;
336	  for (const m of p.meds) {
337	    if (CLASS_SKIP(m)) continue;
338	    const before = m.history.filter((h) => h.by !== "A" && h.by !== "P" && (!h.at.includes("T") || ms(h.at) < ms(enc.start)));
339	    const st0 = before[before.length - 1]?.status;
340	    if (st0 !== "active" && st0 !== "held") continue;
341	    const aEntries = m.history.filter((h) => h.by === "A" && ms(h.at) <= ms(doc.signedAt) && ms(h.at) >= ms(enc.start));
342	    const last = aEntries[aEntries.length - 1];
343	    const status = !last ? (isDischarge ? "active" : "unknown") : last.status === "held" ? "held" : last.status === "stopped" ? "stopped" : "active";
344	    const d = medDoseAt(p, m.id, last?.dose ? doc.signedAt : enc.start);
345	    e.medications.push(row("medications", {
346	      ingredient: d.drug.ingredient, names: [`${d.drug.ingredient} ${d.drug.strength} mg ${d.drug.form}`], ingredientDerivable: true, status,
347	      dose: doseOf(d.dose), frequency: FREQ_OK[d.frequency],
348	    }, [m.id], "A", ix, modality(m, "A"), ["T15", ...(status === "held" ? ["T1"] : [])]));
349	  }
350	
351	  // Allergies: the latest document's list, plus adverse drug effects recorded as diagnoses in any document.
352	  const seen = new Set<string>();
353	  for (const a of p.allergies.filter((x) => x.visibility.A && ms(x.recordedAt.includes("T") ? x.recordedAt : x.recordedAt + "T00:00:00Z") < ms(enc.start))) {
354	    seen.add(a.id);
355	    const sev = a.type === "intolerance" ? "mild" : a.criticality === "high" ? "severe" : "moderate";
356	    e.allergies.push(row("allergies", { substance: a.substance.display, type: a.type === "adverse-reaction" ? "adverse_reaction" : a.type, ...(sev !== "moderate" ? { criticality: a.criticality } : {}) } as AllergyKey, [a.id], "A", ix, modality(a, "A"), ["T18"]));
357	  }
358	  // A diagnosis that names a drug-caused condition (SGLT2i-associated DKA, ACE-inhibitor angioedema) is the
359	  // view's allergy row too: the truth links the reaction to the condition it caused (`manifestation`).
360	  for (const { doc: d } of docs) for (const it of d.plan ?? []) {
361	    if (it.kind !== "dx") continue;
362	    const a = p.allergies.find((x) => x.manifestation === it.conditionId && x.visibility.A);
363	    if (!a || seen.has(a.id)) continue;
364	    seen.add(a.id);
365	    e.allergies.push(row("allergies", { substance: a.substance.display, type: a.type === "adverse-reaction" ? "adverse_reaction" : a.type } as AllergyKey, [a.id], "A", ix, modality(a, "A"), ["T18"]));
366	  }
367	  for (const { doc: d } of docs) for (const it of d.plan ?? []) {
368	    if (it.kind !== "adverse-dx" || seen.has(it.allergyId)) continue;
369	    seen.add(it.allergyId);
370	    const a = p.allergies.find((x) => x.id === it.allergyId)!;
371	    e.allergies.push(row("allergies", { substance: a.substance.display, type: "adverse_reaction" } as AllergyKey, [a.id], "A", ix, modality(a, "A"), ["T18"]));
372	  }
373	
374	  // Problems: latest appearance of each condition in any document's diagnosis or history list.
375	  const appear = new Map<string, { status: string; label: string }>();
376	  for (const { doc: d } of docs) for (const it of d.plan ?? []) {
377	    if (it.kind === "dx") {
378	      const c = p.conditions.find((x) => x.id === it.conditionId)!;
379	      const hs = c.history.filter((h) => h.recordedBy === "A" && ms(h.at.includes("T") ? h.at : h.at + "T00:00:00Z") <= ms(d.signedAt));
380	      appear.set(c.id, { status: hs[hs.length - 1]?.status ?? "active", label: [...hs].reverse().find((h) => h.label)?.label ?? c.name });
381	    } else if (it.kind === "history") {
382	      const c = p.conditions.find((x) => x.id === it.conditionId)!;
383	      appear.set(c.id, { status: "active", label: it.label ?? c.name });
384	    }
385	  }
386	  for (const [cid, a] of appear) {
387	    const c = p.conditions.find((x) => x.id === cid)!;
388	    const icd = c.coding.find((x) => x.system === "icd10")!.code;
389	    if (a.status === "ruled-out" || a.status === "working") {
390	      e.anti.push(row("problems", { reason: `diagnosis ${a.status} in the latest document that lists it`, family: family(icd, a.label), condition: a.label }, [c.id], "A", ix, "narrated", ["T12"]));
391	      continue;
392	    }
393	    e.problems.push(row("problems", { family: family(icd, a.label), condition: a.label, icd10: icd, status: a.status === "resolved" ? "resolved" : "active" } as ProblemKey, [c.id], "A", ix, modality(c, "A")));
394	  }
395	
396	  // Labs: every result copied into an in-scope document, once.
397	  const labIds = new Set<string>();
398	  for (const { doc: d } of docs) for (const it of d.plan ?? []) if (it.kind === "lab") for (const id of it.labIds) labIds.add(id);
399	  for (const id of labIds) {
400	    const l = p.labs.find((x) => x.id === id)!;
401	    const a = analyteName(l.analyte);
402	    e.labs.push(row("labs", {
403	      analyte: a, value: round(l.value, DEC_A[l.analyte] ?? 1), ...(l.comparator ? { comparator: l.comparator } : {}), unit: UNIT[a], collected: l.collectedAt,
404	      ...(a === "egfr" ? { egfr_equation: "ckd-epi-2021" } : {}),
405	    }, [l.id], "A", ix, modality(l, "A"), ["T14", "T10"]));
406	  }
407	
408	  // Vitals.
409	  const vids = new Set<string>();
410	  for (const { doc: d } of docs) for (const it of d.plan ?? []) if (it.kind === "vitals") vids.add(it.vitalId);
411	  for (const id of vids) {
412	    const v = p.vitals.find((x) => x.id === id)!;
413	    e.vitals.push(row("vitals", {
414	      setting: "hospital", local_time: wall(v.at), ...(v.bp ? { systolic_mmhg: v.bp.systolic, diastolic_mmhg: v.bp.diastolic } : {}),
415	      ...(v.pulse !== undefined ? { pulse_bpm: v.pulse } : {}), ...(v.weightKg !== undefined ? { weight_kg: v.weightKg } : {}),
416	    } as VitalKey, [v.id], "A", ix, "structured", ["T10"]));
417	  }
418	}
419	
420	// HomeLog: day pages (supersede on edit) and My Medicines saves (each restates the list).
421	const BRAND_OK = (name: string, ingredient: string, brand?: string) => {
422	  const n = name.toLowerCase();
423	  return n.includes(ingredient.split(" ").slice(-1)[0]) || (!!brand && n.includes(brand.toLowerCase()));
424	};
425	
426	function homelog(p: Patient, t: number, e: Expected, ix: TrapIndex) {
427	  const plan = p.home;
428	  if (!plan) return;
429	  const saves = plan.listSaves.filter((s) => ms(localAt(`${s.at}T00:00`)) <= t);
430	  const save = saves[saves.length - 1];
431	  if (save) save.entries.forEach((en, i) => {
432	    const m = p.meds.find((x) => x.id === en.medId)!;
433	    const d = drug(m.product);
434	    // HomeLog has no paused status: a paused drug left as 'taking' with a note saying so is held by the patient's account.
435	    const paused = en.status === "taking" && /stop for now|on hold|paused/i.test(en.note ?? "");
436	    e.medications.push(row("medications", {
437	      ingredient: d.ingredient, names: [en.name], ingredientDerivable: !!en.picked || BRAND_OK(en.name, d.ingredient, d.brand),
438	      status: en.status === "stopped" ? "stopped" : paused ? "held" : "active", status_since: en.status === "stopped" ? en.stopped : undefined,
439	    }, [m.id], "P", ix, modality(m, "P"), [...(m.otc ? ["T13"] : []), ...(paused ? ["T1"] : [])]));
440	    e.medications[e.medications.length - 1].order = (en.status === "stopped" ? 0 : 1000) + i;
441	  });
442	  for (const v of p.vitals.filter((x) => x.source === "P" && ms(x.at) <= t)) {
443	    const typoLive = v.typo && ms(localAt(`${v.typo.fixedAt.slice(0, 10)}T00:00`)) > t;
444	    if (v.duplicateOf) {
445	      e.anti.push(row("vitals", { reason: "typed duplicate of a device reading", setting: "home", local_time: wall(v.at), ...(v.bp ? { systolic_mmhg: v.bp.systolic } : {}), ...(v.glucose ? { glucose_mg_dl: v.glucose } : {}) }, [v.id], "P", ix, "structured", ["T14"]));
446	      continue;
447	    }
448	    if (v.kind === "home-glucose") {
449	      const mmol = v.renderedUnit === "mmol/L";
450	      const g = v.glucose! > 600 ? 600 : v.glucose! < 20 ? 20 : mmol ? Math.round(Math.round((v.glucose! / MGDL_PER_MMOL_GLUCOSE) * 10) / 10 * MGDL_PER_MMOL_GLUCOSE) : v.glucose!;
451	      e.vitals.push(row("vitals", { setting: "home", local_time: wall(v.at), glucose_mg_dl: g } as VitalKey, [v.id], "P", ix, "structured", mmol ? ["T6"] : []));
452	    } else {
453	      const bp = typoLive ? { ...v.bp!, ...v.typo } : v.bp!;
454	      if (v.typo && !typoLive) e.anti.push(row("vitals", { reason: "typo corrected on a superseding day page", setting: "home", local_time: wall(v.at), systolic_mmhg: v.typo.systolic ?? bp.systolic, diastolic_mmhg: v.typo.diastolic ?? bp.diastolic }, [v.id], "P", ix, "structured", ["T14"]));
455	      e.vitals.push(row("vitals", { setting: "home", local_time: wall(v.at), systolic_mmhg: bp.systolic, diastolic_mmhg: bp.diastolic, ...(v.pulse !== undefined ? { pulse_bpm: v.pulse } : {}) } as VitalKey, [v.id], "P", ix, "structured", v.typo ? ["T14"] : []));
456	    }
457	  }
458	}
459	
460	// ─── Condition families (used to match problem rows) ──────────────────────────────────────────────
461	
462	const ICD_FAMILY: [RegExp, string][] = [
463	  [/^I1[0-3]/, "hypertension"], [/^E1[013]\.1/, "dka"], [/^E11/, "type 2 diabetes"], [/^N18/, "ckd"], [/^E78/, "hyperlipidemia"],
464	  [/^F3[23]/, "depression"], [/^E66/, "obesity"], [/^I50/, "heart failure"], [/^M10/, "gout"], [/^M17/, "knee osteoarthritis"],
465	  [/^E03/, "hypothyroidism"], [/^E87\.1/, "hyponatremia"], [/^E87\.5/, "hyperkalemia"], [/^N17/, "aki"], [/^K85/, "pancreatitis"],
466	  [/^I2[0-5]/, "acs"], [/^J1[2-8]/, "pneumonia"], [/^T78\.3/, "angioedema"], [/^F41/, "anxiety"],
467	];
468	const TEXT_FAMILY: [RegExp, string][] = [
469	  [/ketoacidosis|\bDKA\b/i, "dka"], [/hypertensi|\bHTN\b/i, "hypertension"], [/kidney disease|\bCKD\b/i, "ckd"], [/type 2 diabetes|\bT2DM\b|diabetes mellitus/i, "type 2 diabetes"],
470	  [/hyperlipid|dyslipid|cholesterol/i, "hyperlipidemia"], [/depress/i, "depression"], [/obes/i, "obesity"], [/heart failure|HFrEF/i, "heart failure"],
471	  [/gout/i, "gout"], [/osteoarthritis/i, "knee osteoarthritis"], [/hypothyroid/i, "hypothyroidism"], [/hyponatr/i, "hyponatremia"],
472	  [/hyperkal/i, "hyperkalemia"], [/acute kidney injury|\bAKI\b/i, "aki"], [/pancreatitis/i, "pancreatitis"], [/coronary|\bACS\b|chest pain/i, "acs"],
473	  [/pneumonia/i, "pneumonia"], [/angioedema/i, "angioedema"], [/anxiety/i, "anxiety"],
474	];
475	
476	/** A coarse condition identity: ICD-10 code family first, then wording, then the 3-character category. */
477	export function family(icd10: string | undefined, text: string | undefined): string {
478	  if (icd10) for (const [re, f] of ICD_FAMILY) if (re.test(icd10)) return f;
479	  if (text) for (const [re, f] of TEXT_FAMILY) if (re.test(text)) return f;
480	  if (icd10) return icd10.slice(0, 3);
481	  return (text ?? "").toLowerCase().trim();
482	}
483	
484	export { inZone };
485	
486	// ─── Merged (end-to-end) key ───────────────────────────────────────────────────────────────────────
487	
488	/**
489	 * The merged chart key from the truth's answer keys (packages/truth/src/keys.ts), in the same row form.
490	 * Medications: active and held only (the merged view the consumer shows). eGFR: the value as reported
491	 * under the views' eGFR rule (the non-race variant on CKD-EPI 2009 rows), since the truth's recomputed
492	 * CKD-EPI 2021 value for old rows needs demographics no mapper is given.
493	 */
494	export function mergedExpected(p: Patient, keys: Record<string, any>, ix: TrapIndex): Expected {
495	  const e: Expected = { medications: [], problems: [], allergies: [], labs: [], vitals: [], anti: [] };
496	  const traps = (ids: string[]) => [...new Set(ids.flatMap((id) => [...(ix.fact.get(id) ?? [])]))].sort((a, b) => +a.slice(1) - +b.slice(1));
497	  const mk = <F>(view: KeyRow<F>["view"], fields: F, basis: string[]): KeyRow<F> => ({ view, fields, basis, traps: traps(basis), modality: "structured" });
498	  for (const m of keys["active-meds"]) e.medications.push(mk("medications", {
499	    ingredient: m.medication, names: [m.product], ingredientDerivable: true, status: m.status, status_since: m.status === "held" ? m.since : undefined, dose: doseOf(m.dose ?? undefined),
500	  } as MedKey, m.basis));
501	  for (const [list, status] of [["active", "active"], ["resolved", "resolved"]] as const) for (const c of keys.problems[list]) e.problems.push(mk("problems", {
502	    family: family(c.icd10, c.condition), condition: c.condition, icd10: c.icd10, status, ...(/^N18/.test(c.icd10) ? { ckd_stage: stageOf(c.stage).ckd_stage } : {}), onset: c.onset,
503	  } as ProblemKey, c.basis));
504	  for (const a of keys.allergies) e.allergies.push(mk("allergies", { substance: a.substance, type: a.type === "adverse-reaction" ? "adverse_reaction" : a.type, criticality: a.criticality } as AllergyKey, a.basis));
505	  for (const [analyte, series] of Object.entries(keys["lab-series"]) as [string, any[]][]) for (const l of series) {
506	    const a = analyteName(analyte);
507	    let value = l.value, comparator = l.comparator, eq: string | undefined;
508	    if (a === "egfr") {
509	      const rep = (l.reported ?? []).find((r: any) => r.equation === "ckd-epi-2009-nonaa") ?? (l.reported ?? []).find((r: any) => r.equation === "ckd-epi-2021");
510	      if (rep) { value = rep.value; comparator = rep.comparator; eq = rep.equation === "ckd-epi-2021" ? "ckd-epi-2021" : "ckd-epi-2009"; } else eq = "ckd-epi-2021";
511	    }
512	    e.labs.push(mk("labs", { analyte: a, value, ...(comparator ? { comparator } : {}), unit: UNIT[a], collected: l.collected, ...(eq ? { egfr_equation: eq } : {}) } as LabKey, l.basis));
513	  }
514	  const v = keys.vitals;
515	  const finish = () => restrictToRecords(p, e, ix);
516	  for (const [list, setting] of [["clinic", "clinic"], ["hospital", "hospital"], ["home_bp", "home"], ["home_glucose", "home"]] as const) for (const x of v[list]) e.vitals.push(mk("vitals", {
517	    setting, local_time: x.local_time, ...(x.systolic !== undefined ? { systolic_mmhg: x.systolic, diastolic_mmhg: x.diastolic } : {}),
518	    ...(x.repeat ? { repeat_systolic_mmhg: x.repeat.systolic, repeat_diastolic_mmhg: x.repeat.diastolic } : {}), ...(x.pulse !== undefined ? { pulse_bpm: x.pulse } : {}),
519	    ...(x.weight_kg !== undefined ? { weight_kg: x.weight_kg } : {}), ...(x.glucose_mg_dl !== undefined ? { glucose_mg_dl: Math.min(600, x.glucose_mg_dl) } : {}),
520	  } as VitalKey, x.basis));
521	  return finish();
522	}
523	
524	/**
525	 * The merged key restricted to what the records carry: a fact no source renders is dropped, and a
526	 * field (dose, onset, CKD stage, status date, criticality) is scored only if some source's own key
527	 * carries it for that fact.
528	 */
529	function restrictToRecords(p: Patient, e: Expected, ix: TrapIndex): Expected {
530	  const per = (Object.keys(SOURCE_KEY) as string[]).filter((s) => p.sources[SOURCE_KEY[s]]).map((s) => expectedFor(p, s, "2026-10-13", ix));
531	  const views = ["medications", "problems", "allergies", "labs", "vitals"] as const;
532	  for (const view of views) {
533	    const src = per.flatMap((x) => x[view] as KeyRow<any>[]);
534	    (e as any)[view] = (e[view] as KeyRow<any>[]).flatMap((r) => {
535	      const same = src.filter((x) => x.basis.some((b) => r.basis.includes(b)));
536	      if (!same.length) return [];
537	      const f = { ...r.fields };
538	      for (const k of ["dose", "onset", "ckd_stage", "status_since", "criticality", "frequency"]) if (k in f && !same.some((x) => x.fields[k] !== undefined)) delete f[k];
539	      return [{ ...r, fields: f }];
540	    });
541	  }
542	  return e;
543	}
544

